"""Split a line read from file into a name/sequence tuple

    Arguments:
      line: line of text with name and sequence separated by tab.

    Returns:
      (name,sequence) tuple.

    """
def split_line(line: Any) -> object {
    name = line.strip('\n').split('\t')[0];
    seq = line.strip('\n').split('\t')[-1];
    return (name, seq);
}

"""
    Return an appropriate error message for an
    `~plasmapy.utils.InvalidParticleError`.
    """
def _invalid_particle_errmsg(
    argument: Any, mass_numb: Any = None, Z: Any = None
) -> object {
    errmsg = f"The argument {repr(argument)} ";
    if ((mass_numb is not None) or (Z is not None)) {
        errmsg += "with ";
    }
    if (mass_numb is not None) {
        errmsg += f"mass_numb = {repr(mass_numb)} ";
    }
    if ((mass_numb is not None) and (Z is not None)) {
        errmsg += "and ";
    }
    if (Z is not None) {
        errmsg += f"integer charge Z = {repr(Z)} ";
    }
    errmsg += "does not correspond to a valid particle.";
    return errmsg;
}

