    Heuristic for default boxplot grouping
    """
def default_grouping(datasets: Any, date_field: Any = None) -> object {
    if ((datasets > 20) and date_field) {
        return "year";
    } elif ((datasets > 10) or not date_field) {
        return "series";
    } else {
        return "series-year";
    }
}

